import React from 'react';
import PostItem from './PostItem';
import './PostList.css';

const PostList = ({ posts, loading, onEdit, onDelete }) => {
  // Show loading spinner if fetching posts
  if (loading && posts.length === 0) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border text-primary" role="status"></div>
        <p className="text-muted mt-2">Loading posts...</p>
      </div>
    );
  }

  // Show empty state if no posts exist
  if (posts.length === 0) {
    return (
      <div className="card text-center p-5 shadow-sm">
        <h5 className="text-muted mb-0">No posts yet. Create your first post using the form!</h5>
      </div>
    );
  }

  return (
    <div>
      {/* Header showing total count */}
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h5 className="mb-0 text-dark fw-bold">Published Posts</h5>
        <span className="badge bg-secondary">{posts.length} {posts.length === 1 ? 'post' : 'posts'}</span>
      </div>

      {/* Grid of posts */}
      <div className="row g-3">
        {posts.map((post) => (
          <div key={post._id} className="col-12 col-md-6">
            <PostItem
              post={post}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default PostList;
